package com.autocare.platform.order;
import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;

class LocalRefundChannelTest {
    static final String NO="R"+"a".repeat(32);
    static String body(String status){return "{\"event_id\":\"00000000-0000-0000-0000-000000000001\",\"refund_id\":1,\"refund_no\":\""+NO+"\",\"payment_id\":2,\"channel_refund_no\":\"test-refund\",\"status\":\""+status+"\",\"amount\":\"12.34\",\"currency\":\"CNY\",\"occurred_at\":\"2026-10-07T00:00:00Z\"}";}
    LocalTestRefundChannel channel(){return new LocalTestRefundChannel(LocalTestPaymentChannelTest.KEY,Clock.fixed(LocalTestPaymentChannelTest.NOW,ZoneOffset.UTC),"");}
    @Test void signatureAndCanonicalEventHash()throws Exception{var channel=channel();String time=""+LocalTestPaymentChannelTest.NOW.getEpochSecond(),nonce=UUID.randomUUID().toString();byte[] raw=body("SUCCEEDED").getBytes(StandardCharsets.UTF_8);var n=channel.verify(raw,time,nonce,LocalTestPaymentChannelTest.sign(raw,time,nonce));byte[] pretty=(" \n"+body("SUCCEEDED")).getBytes(StandardCharsets.UTF_8);assertEquals(n.hash(),channel.verify(pretty,time,nonce,LocalTestPaymentChannelTest.sign(pretty,time,nonce)).hash());assertThrows(RuntimeException.class,()->channel.verify(body("FAILED").getBytes(StandardCharsets.UTF_8),time,nonce,LocalTestPaymentChannelTest.sign(raw,time,nonce)));}
    @Test void unknownFieldsDuplicateKeysZeroAmountCurrencyAndTrailingJsonRejected()throws Exception{String time=""+LocalTestPaymentChannelTest.NOW.getEpochSecond(),nonce=UUID.randomUUID().toString();for(String b:List.of(body("SUCCEEDED").replace("12.34","0.00"),body("SUCCEEDED").replace("CNY","USD"),body("SUCCEEDED").replace("{","{\"refund_id\":2,"),body("SUCCEEDED").replace("{","{\"success\":true,"),body("SUCCEEDED")+" {}")){byte[] raw=b.getBytes(StandardCharsets.UTF_8);assertThrows(RuntimeException.class,()->channel().verify(raw,time,nonce,LocalTestPaymentChannelTest.sign(raw,time,nonce)));}}
    @Test void unsignedExpiredAndLargeBodiesRejected()throws Exception{byte[] raw=body("SUCCEEDED").getBytes(StandardCharsets.UTF_8);String time=""+(LocalTestPaymentChannelTest.NOW.getEpochSecond()-301),nonce=UUID.randomUUID().toString();assertThrows(RuntimeException.class,()->channel().verify(raw,time,nonce,LocalTestPaymentChannelTest.sign(raw,time,nonce)));assertThrows(RuntimeException.class,()->channel().verify(new byte[16385],time,nonce,LocalTestPaymentChannelTest.sign(raw,time,nonce)));assertThrows(RuntimeException.class,()->channel().verify(raw,null,null,null));}
    @Test void noProductionOrExternalAdapterCanBeEnabled(){for(String url:List.of("http://example.com","http://user@localhost","https://localhost","http://localhost/x"))assertThrows(IllegalArgumentException.class,()->new LocalTestRefundChannel(LocalTestPaymentChannelTest.KEY,Clock.systemUTC(),url));var env=new org.springframework.mock.env.MockEnvironment();var channels=new RefundChannels(env,new PaymentChannels(env,Clock.systemUTC()),Clock.systemUTC());assertThrows(RuntimeException.class,()->channels.get("WECHAT"));assertThrows(RuntimeException.class,()->channels.callback());}
    @Test void supplierDistinguishesUnknownAndKnownPendingAndSignsOriginalRequest()throws Exception{
        var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);var failure=new java.util.concurrent.atomic.AtomicReference<Throwable>();var status=new java.util.concurrent.atomic.AtomicInteger(404);var calls=new java.util.concurrent.atomic.AtomicInteger();
        server.createContext("/refunds/",e->{try{assertEquals("/refunds/"+NO,e.getRequestURI().getPath());if("POST".equals(e.getRequestMethod())){calls.incrementAndGet();var raw=e.getRequestBody().readAllBytes();var h=e.getRequestHeaders();assertEquals(NO,h.getFirst("Idempotency-Key"));assertEquals(LocalTestPaymentChannelTest.sign(raw,h.getFirst("X-Test-Timestamp"),h.getFirst("X-Test-Nonce")),h.getFirst("X-Test-Signature"));var n=channel().mapper.readTree(raw);assertEquals("12.34",n.path("amount").asText());assertEquals(2,n.path("payment_id").asLong());}e.sendResponseHeaders(status.get(),-1);}catch(Throwable t){failure.set(t);}finally{e.close();}});server.start();
        try{var channel=new LocalTestRefundChannel(LocalTestPaymentChannelTest.KEY,Clock.fixed(LocalTestPaymentChannelTest.NOW,ZoneOffset.UTC),"http://127.0.0.1:"+server.getAddress().getPort());var r=new RefundChannel.Request(1,NO,2,"P"+"b".repeat(32),"original",new java.math.BigDecimal("12.34"),"CNY");assertFalse(channel.query(r).exists());status.set(202);assertTrue(channel.submit(r).exists());assertTrue(channel.query(r).exists());assertEquals(1,calls.get());assertNull(failure.get());}finally{server.stop(0);}
    }
    @Test void signedSupplierResponseIsBoundToRefundAndFrozenAmount()throws Exception{
        var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/refunds/",e->{try{byte[] raw=body("SUCCEEDED").getBytes(StandardCharsets.UTF_8);String time=""+LocalTestPaymentChannelTest.NOW.getEpochSecond(),nonce=UUID.randomUUID().toString();e.getResponseHeaders().add("X-Test-Timestamp",time);e.getResponseHeaders().add("X-Test-Nonce",nonce);e.getResponseHeaders().add("X-Test-Signature",LocalTestPaymentChannelTest.sign(raw,time,nonce));e.sendResponseHeaders(200,raw.length);e.getResponseBody().write(raw);}catch(Exception t){throw new RuntimeException(t);}finally{e.close();}});server.start();
        try{var channel=new LocalTestRefundChannel(LocalTestPaymentChannelTest.KEY,Clock.fixed(LocalTestPaymentChannelTest.NOW,ZoneOffset.UTC),"http://127.0.0.1:"+server.getAddress().getPort());var r=new RefundChannel.Request(1,NO,2,"P"+"b".repeat(32),"original",new java.math.BigDecimal("12.34"),"CNY");assertEquals("SUCCEEDED",channel.query(r).notice().status());assertThrows(RuntimeException.class,()->channel.query(new RefundChannel.Request(2,NO,2,r.paymentNo(),r.transaction(),r.amount(),r.currency())));assertThrows(RuntimeException.class,()->channel.query(new RefundChannel.Request(1,NO,2,r.paymentNo(),r.transaction(),new java.math.BigDecimal("0.01"),r.currency())));}finally{server.stop(0);}
    }

    @Test void redirectsErrorsOversizedAndSlowBodiesCannotBecomeRefundSuccess()throws Exception{var code=new java.util.concurrent.atomic.AtomicInteger(302);var mode=new java.util.concurrent.atomic.AtomicInteger();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/refunds/",e->{try{if(mode.get()==1){e.sendResponseHeaders(200,16385);e.getResponseBody().write(new byte[16385]);}else if(mode.get()==2){e.sendResponseHeaders(200,0);e.getResponseBody().flush();Thread.sleep(4000);}else{e.getResponseHeaders().add("Location","http://example.test");e.sendResponseHeaders(code.get(),-1);}}catch(Exception ignored){}finally{e.close();}});server.start();try{var channel=new LocalTestRefundChannel(LocalTestPaymentChannelTest.KEY,Clock.fixed(LocalTestPaymentChannelTest.NOW,ZoneOffset.UTC),"http://127.0.0.1:"+server.getAddress().getPort());var r=new RefundChannel.Request(1,NO,2,"P"+"b".repeat(32),"original",new java.math.BigDecimal("12.34"),"CNY");assertThrows(RuntimeException.class,()->channel.query(r));code.set(503);assertThrows(RuntimeException.class,()->channel.query(r));mode.set(1);assertThrows(RuntimeException.class,()->channel.query(r));mode.set(2);long start=System.nanoTime();assertThrows(RuntimeException.class,()->channel.query(r));assertTrue(java.time.Duration.ofNanos(System.nanoTime()-start).toMillis()<3900);}finally{server.stop(0);}}
}
